  Fixture()throws Exception {Application app=RuntimeEnvironment.getApplication();app.deleteDatabase("pocket-world.db");app.getSharedPreferences("private_settings",0).edit().clear().commit();settings=new SettingsStore(app.getSharedPreferences("private_settings",0),new SettingsStore.ApiSecrets(){final java.util.Map<String,String> secrets=new java.util.HashMap<>();public String get(String slot){return secrets.getOrDefault(slot,"");}public void put(String slot,String value){secrets.put(slot,value);}});tasks=new TaskStore(app);
   server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",exchange->{try{posts.incrementAndGet();JSONObject input=new JSONObject(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));Object content=input.getJSONArray("messages").getJSONObject(0).get("content");String prompt=content instanceof String?(String)content:"Synthetic diagnostic image";if(content instanceof JSONArray parts){String url=parts.getJSONObject(1).getJSONObject("image_url").getString("url");byte[] png=java.util.Base64.getDecoder().decode(url.substring("data:image/png;base64,".length()));if(java.nio.ByteBuffer.wrap(png).getLong()!=0x89504e470d0a1a0aL||java.nio.ByteBuffer.wrap(png,16,8).getInt()!=360||java.nio.ByteBuffer.wrap(png,20,4).getInt()!=100)throw new IllegalArgumentException("synthetic PNG mismatch");images.incrementAndGet();}if(input.has("tools")&&transientTools.get()){byte[] unavailable="{\"error\":{\"message\":\"temporary diagnostic fixture failure\"}}".getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(503,unavailable.length);exchange.getResponseBody().write(unavailable);return;}String text=input.has("tools")?"Plain text only":content instanceof String?prompt.substring(prompt.lastIndexOf(' ')+1):"image not confirmed by this fixture";if(change.getAndSet(false))settings.save(new JSONObject().put("model","different-model"));JSONObject message=new JSONObject().put("role","assistant").put("content",text);if(input.has("tools")&&echoTools.get()){String prefix="Call pocket_capability_echo exactly once with token ";String token=prompt.substring(prefix.length(),prompt.indexOf(". Do not answer in text."));message.put("content",JSONObject.NULL).put("tool_calls",new JSONArray().put(new JSONObject().put("id","fixture-echo-call").put("type","function").put("function",new JSONObject().put("name","pocket_capability_echo").put("arguments",new JSONObject().put("token",token).toString()))));}JSONObject response=new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("finish_reason",message.has("tool_calls")?"tool_calls":"stop").put("message",message))).put("usage",new JSONObject().put("prompt_tokens",2).put("completion_tokens",1).put("total_tokens",3));byte[] bytes=response.toString().getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().add("Content-Type","application/json");exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);}catch(Exception problem){throw new RuntimeException(problem);}finally{exchange.close();}});server.start();settings.save(new JSONObject().put("baseUrl","http://127.0.0.1:"+server.getAddress().getPort()+"/v1").put("model","fixture-model").put("sendScreenshots",false));service=new ModelConnectionService(settings,Files.createTempDirectory("probe-catalog").resolve("catalog.json"),Clock.systemUTC());service.install();service.attachOwnerStore(tasks);service.connections();
  }
  void enableCatalog()throws Exception {service.configure(null,ModelBinding.Format.OPENAI,java.net.URI.create(settings.apiConfigForCatalog().baseUrl+"/models"));ModelBinding binding=binding();service.editField(binding,"fixture-model",0,ModelFacts.Field.CHAT_OUTPUT_PARAMETER,ModelFacts.OwnerValue.known(ModelFacts.ChatOutputParameter.MAX_TOKENS),false);assertTrue(settings.apiConfigForCatalog().catalogEnforced);assertTrue(settings.matchesApiCatalogRoute(settings.apiConfigForCatalog()));}
