 @Test public void realTextEndpointIgnoringToolsHasIndependentFailedToolEvidenceAndOriginalUsage()throws Exception {try(Fixture f=new Fixture()){assertNotNull(f.binding());assertNull(f.settings.apiCatalogBinding());assertFalse(f.settings.apiConfigForCatalog().catalogEnforced);JSONObject result=f.service.probe(f.binding(),false,new RunControl());assertEquals("passed",result.getString("text"));assertEquals("unconfirmed",result.getString("tools"));assertEquals("not_requested",result.getString("image"));assertFalse(result.getBoolean("deviceToolsExecuted"));assertFalse(result.getBoolean("capabilityMetadataChanged"));String task=result.getJSONObject("inferenceReference").getString("taskId");assertEquals(2,f.posts.get());assertEquals(2,f.tasks.inferenceUsage(task).getInt("attempts"));assertEquals(0,f.tasks.get(task,false).getJSONArray("operations").length());assertNotNull(f.service.snapshot().optJSONObject("capabilityProbe"));JSONObject selected=f.settings.apiConnectionsSnapshot().getJSONArray("connections").getJSONObject(0);f.settings.setApiConnectionEnabled(selected.getString("id"),selected.getLong("revision"),false);assertNull(f.service.snapshot().optJSONObject("capabilityProbe"));}}
 @Test public void changedConfigStopsBeforeNextProbeAndDoesNotPublishOldEvidence()throws Exception {try(Fixture f=new Fixture()){ModelBinding binding=f.binding();f.change.set(true);assertThrows(SecurityException.class,()->f.service.probe(binding,false,new RunControl()));assertEquals(1,f.posts.get());assertNull(f.service.snapshot().optJSONObject("capabilityProbe"));}}
