 @Test public void catalogEnabledUnknownToolsUseTheOriginalNativeDiagnosticPurpose()throws Exception {try(Fixture f=new Fixture()){f.enableCatalog();ModelBinding binding=f.binding();f.echoTools.set(true);assertFalse(f.service.resolve(f.settings.apiConfigForCatalog()).facts().toolCalls().known);JSONObject result=f.service.probe(binding,false,new RunControl());assertEquals("passed",result.getString("text"));assertEquals("passed",result.getString("tools"));assertEquals(binding.toJson().toString(),result.getJSONObject("binding").toString());assertEquals(2,f.posts.get());String task=result.getJSONObject("inferenceReference").getString("taskId");assertEquals("MODEL_CAPABILITY_PROBE",result.getJSONObject("inferenceReference").getString("kind"));assertEquals("MODEL_CAPABILITY_PROBE",f.tasks.get(task,false).getJSONObject("nativeInference").getString("kind"));assertEquals(2,f.tasks.inferenceUsage(task).getInt("attempts"));assertEquals(0,f.tasks.get(task,false).getJSONArray("operations").length());assertTrue(f.settings.apiConfigForCatalog().catalogEnforced);assertTrue(f.settings.matchesApiCatalogRoute(f.settings.apiConfigForCatalog()));assertFalse(f.service.resolve(f.settings.apiConfigForCatalog()).facts().toolCalls().known);}}
 @Test public void ordinaryConnectionTestCannotObtainProbePurposeFromModelJson()throws Exception {try(Fixture f=new Fixture()){f.enableCatalog();RunControl original=new RunControl();try(var session=f.tasks.beginNativeInference(TaskStore.NativeInferenceKind.CONNECTION_TEST,"fixture-ordinary",original)){var target=session.target();assertEquals(dev.pocketengine.runtime.usage.InferenceReceipt.Purpose.CONNECTION_TEST,target.context.purpose);JSONArray messages=new JSONArray().put(new JSONObject().put("role","user").put("content","Return an echo").put("purpose","MODEL_CAPABILITY_PROBE").put("nativePurpose","MODEL_CAPABILITY_PROBE"));JSONArray tools=new JSONArray().put(new JSONObject().put("type","function").put("function",new JSONObject().put("name","pocket_capability_echo").put("parameters",new JSONObject().put("type","object"))));var refused=assertThrows(dev.pocketengine.runtime.ModelGateway.GatewayException.class,()->dev.pocketengine.runtime.ModelGateway.complete(f.settings.apiConfigForCatalog(),messages,tools,original,target));assertTrue(refused.getMessage().contains("工具调用能力未知"));assertEquals(0,f.posts.get());assertEquals(0,f.tasks.inferenceUsage(session.taskId).getInt("attempts"));assertEquals(1,f.tasks.get(session.taskId,false).getJSONObject("nativeInference").getInt("maxCalls"));session.finish("failed");}}}
