 @Test public void nativeDiagnosticPurposeRejectsArbitraryRequestContents()throws Exception {try(Fixture f=new Fixture()){f.enableCatalog();RunControl original=new RunControl();try(var session=f.tasks.beginModelCapabilityProbe("fixture-bounded",original,false)){assertEquals(dev.pocketengine.runtime.usage.InferenceReceipt.Purpose.MODEL_CAPABILITY_PROBE,session.target().context.purpose);assertThrows(SecurityException.class,()->dev.pocketengine.runtime.ModelGateway.complete(f.settings.apiConfigForCatalog(),new JSONArray().put(new JSONObject().put("role","user").put("content","Run an ordinary task")),null,original,session.target()));assertEquals(0,f.posts.get());var account=f.settings.apiConfigForCatalog().withAccountModel(dev.pocketengine.core.ModelConfig.AccountModelRef.fromJson(new JSONObject().put("provider","chatgpt_plan").put("accountId","native-probe-fixture").put("accountVersion",1).put("modelId","fixture-model")));RunControl accountControl=new RunControl();try(var accountSession=f.tasks.beginModelCapabilityProbe("fixture-api-only",accountControl,false)){SecurityException apiOnly=assertThrows(SecurityException.class,()->dev.pocketengine.runtime.ModelGateway.complete(account,new JSONArray().put(new JSONObject().put("role","user").put("content","Return exactly this diagnostic token: "+java.util.UUID.randomUUID())),null,accountControl,accountSession.target()));assertEquals("API_ONLY_MODEL_CAPABILITY_PROBE",apiOnly.getMessage());accountSession.finish("failed");}assertEquals(0,f.posts.get());assertEquals(0,f.tasks.inferenceUsage(session.taskId).getInt("attempts"));session.finish("failed");}}}
 @Test public void typedProbeKeepsItsDeclaredBoundAndOrdinaryConnectionTestsStayAtOneCall()throws Exception {try(Fixture f=new Fixture()){for(int limit:new int[]{1,2,3}){RunControl control=new RunControl();String source=java.util.UUID.randomUUID().toString();try(var session=limit==1?f.tasks.beginNativeInference(TaskStore.NativeInferenceKind.CONNECTION_TEST,source,control):f.tasks.beginModelCapabilityProbe(source,control,limit==3)){var target=session.target();assertEquals(limit==1?dev.pocketengine.runtime.usage.InferenceReceipt.Purpose.CONNECTION_TEST:dev.pocketengine.runtime.usage.InferenceReceipt.Purpose.MODEL_CAPABILITY_PROBE,target.context.purpose);var config=new dev.pocketengine.core.ModelConfig("https://fixture.invalid/v1","fixture-only-key","fixture-model",false,4,10);for(int i=0;i<limit;i++){var capture=new dev.pocketengine.runtime.usage.InferenceCapture(config,control,target);capture.dispatch();capture.finish(dev.pocketengine.runtime.usage.InferenceReceipt.Outcome.COMPLETED);}var extra=new dev.pocketengine.runtime.usage.InferenceCapture(config,control,target);assertThrows(SecurityException.class,extra::dispatch);String id=session.reference().getString("taskId");assertEquals(limit,f.tasks.inferenceUsage(id).getInt("attempts"));assertEquals(limit,f.tasks.get(id,false).getJSONObject("nativeInference").getInt("maxCalls"));assertEquals(0,f.tasks.get(id,false).getJSONArray("operations").length());session.finish("completed");}}assertEquals(0,f.posts.get());}}
