 @Test public void explicitSyntheticImageStaysWithinThreePhysicalReceiptsWithoutReadingTheScreen()throws Exception {try(Fixture f=new Fixture()){JSONObject result=f.service.probe(f.binding(),true,new RunControl());assertEquals("passed",result.getString("text"));assertEquals("unconfirmed",result.getString("tools"));assertEquals("unconfirmed",result.getString("image"));assertEquals(3,f.posts.get());assertEquals(1,f.images.get());String task=result.getJSONObject("inferenceReference").getString("taskId");assertEquals(3,f.tasks.inferenceUsage(task).getInt("attempts"));assertEquals(3,f.tasks.get(task,false).getJSONObject("nativeInference").getInt("maxCalls"));assertEquals(0,f.tasks.get(task,false).getJSONArray("operations").length());assertFalse(result.getBoolean("capabilityMetadataChanged"));}}
 @Test public void transientToolFailureRemainsUnconfirmedWithoutRetryOrCatalogMutation()throws Exception {try(Fixture f=new Fixture()){f.transientTools.set(true);JSONObject result=f.service.probe(f.binding(),false,new RunControl());assertEquals("passed",result.getString("text"));assertEquals("unconfirmed",result.getString("tools"));assertEquals(2,f.posts.get());assertEquals(2,f.tasks.inferenceUsage(result.getJSONObject("inferenceReference").getString("taskId")).getInt("attempts"));assertFalse(result.getBoolean("capabilityMetadataChanged"));}}
 @Test public void changingSelectionAwayAndBackDoesNotReviveAnOldProbe()throws Exception {try(Fixture f=new Fixture()){JSONObject result=f.service.probe(f.binding(),false,new RunControl());assertNotNull(f.service.snapshot().optJSONObject("capabilityProbe"));JSONObject first=f.settings.apiConnectionsSnapshot().getJSONArray("connections").getJSONObject(0);JSONObject other=f.settings.saveApiConnection("",0,"Other diagnostic fixture",new JSONObject().put("provider","openai_chat").put("baseUrl",f.settings.apiConfigForCatalog().baseUrl).put("model","different-fixture"));f.service.selectConnection(other.getString("id"),other.getLong("revision"));assertNull(f.service.snapshot().optJSONObject("capabilityProbe"));f.service.selectConnection(first.getString("id"),first.getLong("revision"));assertEquals(result.getString("configurationDigest"),ModelRoutePlan.configurationDigest(f.settings.apiConfigForCatalog()));assertNull(f.service.snapshot().optJSONObject("capabilityProbe"));assertEquals(2,f.posts.get());}}

 @Test public void genericKindsAndOrdinaryTaskTargetsCannotIssueDiagnosticAuthority()throws Exception {try(Fixture f=new Fixture()){assertThrows(SecurityException.class,()->f.tasks.beginNativeInference(TaskStore.NativeInferenceKind.MODEL_CAPABILITY_PROBE,"not-a-typed-probe",new RunControl()));RunControl ordinary=new RunControl();try(var session=f.tasks.beginNativeInference(TaskStore.NativeInferenceKind.CONNECTION_TEST,"ordinary-kind",ordinary)){assertThrows(SecurityException.class,()->f.tasks.journal(session.taskId,session.runId,session.epoch,ordinary).inferenceTarget(dev.pocketengine.runtime.usage.InferenceReceipt.Purpose.MODEL_CAPABILITY_PROBE,""));session.finish("failed");}RunControl diagnostic=new RunControl();try(var session=f.tasks.beginModelCapabilityProbe("only-native-probe",diagnostic,false)){assertThrows(SecurityException.class,()->f.tasks.journal(session.taskId,session.runId,session.epoch,diagnostic).beginOperation("phone_click",new JSONObject()));assertEquals(0,f.tasks.get(session.taskId,false).getJSONArray("operations").length());session.finish("completed");}assertEquals(0,f.posts.get());}}

 @Test public void ownerStopAfterFirstCommittedPhysicalReceiptPreventsTheSecondCallWithoutRefund()throws Exception {try(Fixture f=new Fixture()){RunControl original=new RunControl();dev.pocketengine.runtime.usage.InferenceCapture.installPresentationObserver(new dev.pocketengine.runtime.usage.InferenceCapture.Sink(){public void started(dev.pocketengine.runtime.usage.InferenceReceipt receipt){}public void finished(dev.pocketengine.runtime.usage.InferenceReceipt receipt){if(receipt.context.purpose==dev.pocketengine.runtime.usage.InferenceReceipt.Purpose.MODEL_CAPABILITY_PROBE)original.cancel();}});assertThrows(InterruptedException.class,()->f.service.probe(f.binding(),false,original));assertEquals(1,f.posts.get());String task=original.hostRunIdentity().taskId();assertEquals(1,f.tasks.inferenceUsage(task).getInt("attempts"));assertEquals(0,f.tasks.get(task,false).getJSONArray("operations").length());assertEquals("cancelled",f.tasks.get(task,false).getString("status"));assertNull(f.service.snapshot().optJSONObject("capabilityProbe"));}}

 @Test public void exhaustedOriginalDeadlineCannotStartAnotherDiagnosticPhase()throws Exception{try(Fixture f=new Fixture()){RunControl original=new RunControl();try(var session=f.tasks.beginModelCapabilityProbe("deadline-fixture",original,false)){
  JSONArray messages=new JSONArray().put(new JSONObject().put("role","user").put("content","Return exactly this diagnostic token: "+java.util.UUID.randomUUID()));
  assertThrows(Exception.class,()->dev.pocketengine.runtime.ModelGateway.completeBefore(f.settings.apiConfigForCatalog(),messages,null,original,session.target(),System.currentTimeMillis()-1));
  assertEquals(0,f.posts.get());assertEquals(0,f.tasks.inferenceUsage(session.taskId).getInt("attempts"));assertTrue(original.matchesHostRun(session.taskId,session.runId,session.epoch));session.finish("failed");
 }}}

 @Test public void probeReportsPhaseAndLeavesSuccessfulDiagnosticsOutOfRecentModels()throws Exception{try(Fixture f=new Fixture()){JSONObject result=f.service.probe(f.binding(),false,new RunControl());assertEquals("tools",result.getJSONArray("diagnostics").getJSONObject(0).getString("stage"));assertEquals("SYNTHETIC_REPLY_UNCONFIRMED",result.getJSONArray("diagnostics").getJSONObject(0).getString("reason"));assertEquals(f.settings.apiConfigForCatalog().requestTimeoutSeconds*1000L,result.getLong("totalBudgetMillis"));assertEquals(0,f.service.modelPickerSnapshot().getJSONArray("models").getJSONObject(0).getLong("lastUsedAt"));assertEquals(2,f.posts.get());}}

